import SwiftUI

/// Entry point for the XGSail Apple Watch companion. See this folder's
/// README.md for how to add this as a watchOS target to the Capacitor iOS
/// project (it is not generated by `cap sync`).
@main
struct XGSailWatchApp: App {
    init() {
        WatchConnectivityClient.shared.activate()
    }

    var body: some Scene {
        WindowGroup {
            ContentView()
                .environmentObject(Sailing.shared.recorder)
                .environmentObject(Sailing.shared.race)
                .environmentObject(Sailing.shared.wind)
                .tint(Palette.signal)
                .task { await Sailing.shared.recorder.requestAuthorization() }
        }
    }
}
